{"content":"import {
  createSystem,
  InputComponent,
  World,
  UIKitMLAsset,
} from '@iwsdk/core';
import {
  Vector3,
  Mesh,
  MeshStandardMaterial,
  CylinderGeometry,
  RingGeometry,
  SphereGeometry,
  BoxGeometry,
  Group,
  PointLight,
  Color,
  DoubleSide,
  PlaneGeometry,
  AmbientLight,
  DirectionalLight,
  TorusGeometry,
} from 'three';

// === Game State ===
export type GameState = 'menu' | 'playing' | 'paused' | 'results' | 'settings' | 'stats';
export type Rank = 'Jonokuchi' | 'Jonidan' | 'Sandanme' | 'Makushita' | 'Juryo' | 'Maegashira' | 'Komusubi' | 'Sekiwake' | 'Ozeki' | 'Yokozuna';

const RANKS: Rank[] = ['Jonokuchi', 'Jonidan', 'Sandanme', 'Makushita', 'Juryo', 'Maegashira', 'Komusubi', 'Sekiwake', 'Ozeki', 'Yokozuna'];

interface OpponentDef {
  name: string;
  weight: number; // 0.5–2.0, affects push resistance
  speed: number;  // 0.5–1.5
  aggression: number; // 0–1
  technique: number;  // 0–1, dodge/counter chance
  color: number;
}

const OPPONENT_POOL: OpponentDef[] = [
  { name: 'TARO', weight: 0.7, speed: 1.2, aggression: 0.3, technique: 0.2, color: 0x44aaff },
  { name: 'KENJI', weight: 1.0, speed: 1.0, aggression: 0.5, technique: 0.3, color: 0xff6644 },
  { name: 'HIRO', weight: 1.3, speed: 0.8, aggression: 0.6, technique: 0.4, color: 0x44ff88 },
  { name: 'DAICHI', weight: 1.5, speed: 0.7, aggression: 0.7, technique: 0.5, color: 0xffaa22 },
  { name: 'RYU', weight: 0.8, speed: 1.3, aggression: 0.4, technique: 0.6, color: 0xaa44ff },
  { name: 'TAKESHI', weight: 1.8, speed: 0.6, aggression: 0.8, technique: 0.3, color: 0xff4444 },
  { name: 'YOSHI', weight: 0.6, speed: 1.4, aggression: 0.2, technique: 0.7, color: 0x44ffff },
  { name: 'MASA', weight: 1.1, speed: 0.9, aggression: 0.6, technique: 0.5, color: 0xffff44 },
  { name: 'GORO', weight: 2.0, speed: 0.5, aggression: 0.9, technique: 0.2, color: 0xff2222 },
  { name: 'SHIN', weight: 0.9, speed: 1.1, aggression: 0.5, technique: 0.8, color: 0x88ff44 },
  { name: 'KENZO', weight: 1.4, speed: 0.8, aggression: 0.7, technique: 0.6, color: 0xff8844 },
  { name: 'RAIDEN', weight: 1.6, speed: 0.9, aggression: 0.8, technique: 0.7, color: 0xff00ff },
];

interface Wrestler {
  group: Group;
  body: Mesh;
  head: Mesh;
  belt: Mesh;
  arms: Group;
  leftArm: Mesh;
  rightArm: Mesh;
  pos: Vector3;
  vel: Vector3;
  facing: number; // radians
  pushCooldown: number;
  grabCooldown: number;
  dodgeCooldown: number;
  chargeCooldown: number;
  isCharging: boolean;
  chargeTime: number;
  isGrabbing: boolean;
  grabTarget: boolean;
  stagger: number;
  weight: number;
  speed: number;
  isPlayer: boolean;
  hp: number;
  maxHp: number;
  pushAnim: number;
  grabAnim: number;
  dodgeDir: Vector3;
  dodgeTime: number;
  height: number;
}

interface Particle {
  mesh: Mesh;
  vel: Vector3;
  life: number;
  maxLife: number;
}

export interface GameData {
  state: GameState;
  score: number;
  wins: number;
  losses: number;
  currentRank: number;
  matchWins: number;
  totalPushes: number;
  totalDodges: number;
  totalGrabs: number;
  totalRingOuts: number;
  bestWinStreak: number;
  currentStreak: number;
  currentOpponent: OpponentDef | null;
  matchNumber: number;
  roundTime: number;
  difficulty: number; // 0=easy 1=normal 2=hard
  colorScheme: number;
  sfxOn: boolean;
  musicOn: boolean;
  matchResult: 'win' | 'loss' | 'timeout' | null;
  countdownTime: number;
  isCountdown: boolean;
}

const COLOR_SCHEMES = [
  { name: 'Dohyo Classic', bg: 0x1a0a00, ring: 0xcc9944, accent: 0xffdd66, floor: 0x332211 },
  { name: 'Neon Arena', bg: 0x000820, ring: 0x0066ff, accent: 0x00ccff, floor: 0x0a0a2a },
  { name: 'Cherry Blossom', bg: 0x1a0010, ring: 0xff6699, accent: 0xff99cc, floor: 0x2a0a1a },
  { name: 'Thunder', bg: 0x0a0a00, ring: 0xffaa00, accent: 0xffcc44, floor: 0x1a1a0a },
];

const RING_RADIUS = 3.5;
const PUSH_FORCE = 6.0;
const CHARGE_FORCE = 10.0;
const GRAB_DURATION = 0.8;
const DODGE_SPEED = 8.0;
const DODGE_DURATION = 0.25;
const FRICTION = 4.0;
const MATCH_TIME = 60;

export class SumoSystem extends createSystem({}) {
  private world!: World;
  private player!: Wrestler;
  private opponent!: Wrestler;
  private ring!: Group;
  private arena!: Group;
  private particles: Particle[] = [];
  private gameData!: GameData;
  private ringEdgeGlow!: Mesh;
  private crowdLights: PointLight[] = [];
  private shakeIntensity = 0;
  private shakeDecay = 0;
  private cameraOffset = new Vector3();
  private dustParticles: Mesh[] = [];
  private fallGroup: Group | null = null;
  private fallAnim = 0;
  private fallingWrestler: 'player' | 'opponent' | null = null;

  init() {
    this.world = this.getWorld();
    this.gameData = {
      state: 'menu',
      score: 0,
      wins: 0,
      losses: 0,
      currentRank: 0,
      matchWins: 0,
      totalPushes: 0,
      totalDodges: 0,
      totalGrabs: 0,
      totalRingOuts: 0,
      bestWinStreak: 0,
      currentStreak: 0,
      currentOpponent: null,
      matchNumber: 0,
      roundTime: MATCH_TIME,
      difficulty: 1,
      colorScheme: 0,
      sfxOn: true,
      musicOn: true,
      matchResult: null,
      countdownTime: 3,
      isCountdown: false,
    };

    this.loadStats();
    this.buildArena();
    this.player = this.createWrestler(true, 0x00aaff, 1.0, 1.0);
    this.opponent = this.createWrestler(false, 0xff4422, 1.0, 1.0);
    this.resetPositions();
  }

  private loadStats() {
    try {
      const saved = localStorage.getItem('neon-sumo-stats');
      if (saved) {
        const s = JSON.parse(saved);
        this.gameData.wins = s.wins || 0;
        this.gameData.losses = s.losses || 0;
        this.gameData.currentRank = s.currentRank || 0;
        this.gameData.totalPushes = s.totalPushes || 0;
        this.gameData.totalDodges = s.totalDodges || 0;
        this.gameData.totalGrabs = s.totalGrabs || 0;
        this.gameData.totalRingOuts = s.totalRingOuts || 0;
        this.gameData.bestWinStreak = s.bestWinStreak || 0;
      }
    } catch (_) { /* ignore */ }
  }

  private saveStats() {
    try {
      localStorage.setItem('neon-sumo-stats', JSON.stringify({
        wins: this.gameData.wins,
        losses: this.gameData.losses,
        currentRank: this.gameData.currentRank,
        totalPushes: this.gameData.totalPushes,
        totalDodges: this.gameData.totalDodges,
        totalGrabs: this.gameData.totalGrabs,
        totalRingOuts: this.gameData.totalRingOuts,
        bestWinStreak: this.gameData.bestWinStreak,
      }));
    } catch (_) { /* ignore */ }
  }

  private buildArena() {
    const scene = this.world.scene;
    this.arena = new Group();
    scene.add(this.arena);

    // Ambient + directional light
    const ambient = new AmbientLight(0x404060, 0.6);
    scene.add(ambient);
    const dirLight = new DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 5);
    scene.add(dirLight);

    // Ground plane
    const groundGeo = new PlaneGeometry(30, 30);
    const groundMat = new MeshStandardMaterial({ color: 0x1a1a2e, roughness: 0.9 });
    const ground = new Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.05;
    this.arena.add(ground);

    // Ring platform (raised dohyo)
    const platformGeo = new CylinderGeometry(RING_RADIUS + 0.8, RING_RADIUS + 1.2, 0.4, 48);
    const platformMat = new MeshStandardMaterial({ color: 0x886633, roughness: 0.7 });
    const platform = new Mesh(platformGeo, platformMat);
    platform.position.y = 0.15;
    this.arena.add(platform);

    // Ring surface
    const ringGeo = new CylinderGeometry(RING_RADIUS + 0.3, RING_RADIUS + 0.3, 0.05, 48);
    const ringMat = new MeshStandardMaterial({ color: 0xcc9944, roughness: 0.5 });
    const ringSurface = new Mesh(ringGeo, ringMat);
    ringSurface.position.y = 0.36;
    this.arena.add(ringSurface);

    // Ring boundary line (tawara)
    const edgeGeo = new TorusGeometry(RING_RADIUS, 0.08, 8, 64);
    const edgeMat = new MeshStandardMaterial({ color: 0xffdd66, emissive: 0xffdd66, emissiveIntensity: 0.5 });
    this.ringEdgeGlow = new Mesh(edgeGeo, edgeMat);
    this.ringEdgeGlow.rotation.x = -Math.PI / 2;
    this.ringEdgeGlow.position.y = 0.4;
    this.arena.add(this.ringEdgeGlow);

    // Corner posts (4 pillars)
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const px = Math.cos(angle) * (RING_RADIUS + 1.5);
      const pz = Math.sin(angle) * (RING_RADIUS + 1.5);

      const pillarGeo = new CylinderGeometry(0.12, 0.15, 2.5, 8);
      const pillarMat = new MeshStandardMaterial({ color: 0xcc2222, emissive: 0xcc2222, emissiveIntensity: 0.3 });
      const pillar = new Mesh(pillarGeo, pillarMat);
      pillar.position.set(px, 1.25, pz);
      this.arena.add(pillar);

      // Lantern on top
      const lanternGeo = new BoxGeometry(0.3, 0.4, 0.3);
      const lanternMat = new MeshStandardMaterial({ color: 0xff6600, emissive: 0xff6600, emissiveIntensity: 0.6 });
      const lantern = new Mesh(lanternGeo, lanternMat);
      lantern.position.set(px, 2.6, pz);
      this.arena.add(lantern);

      const light = new PointLight(0xff8844, 1.0, 8);
      light.position.set(px, 2.8, pz);
      this.arena.add(light);
      this.crowdLights.push(light);
    }

    // Rope canopy (shimenawa)
    for (let i = 0; i < 4; i++) {
      const angle1 = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const angle2 = ((i + 1) / 4) * Math.PI * 2 + Math.PI / 4;
      const r = RING_RADIUS + 1.5;
      const x1 = Math.cos(angle1) * r, z1 = Math.sin(angle1) * r;
      const x2 = Math.cos(angle2) * r, z2 = Math.sin(angle2) * r;

      const ropeLen = Math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2);
      const ropeGeo = new CylinderGeometry(0.04, 0.04, ropeLen, 6);
      const ropeMat = new MeshStandardMaterial({ color: 0xffcc00, emissive: 0xffcc00, emissiveIntensity: 0.2 });
      const rope = new Mesh(ropeGeo, ropeMat);
      rope.position.set((x1 + x2) / 2, 2.5, (z1 + z2) / 2);
      rope.lookAt(x2, 2.5, z2);
      rope.rotateZ(Math.PI / 2);
      this.arena.add(rope);
    }

    // Spectator stands (simple bleachers)
    for (let row = 0; row < 3; row++) {
      const r = RING_RADIUS + 3 + row * 1.5;
      const count = 16 + row * 8;
      for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const x = Math.cos(angle) * r;
        const z = Math.sin(angle) * r;

        // Seat
        const seatGeo = new BoxGeometry(0.4, 0.3 + row * 0.3, 0.4);
        const seatMat = new MeshStandardMaterial({
          color: new Color().setHSL(Math.random() * 0.1 + 0.55, 0.3, 0.15),
          roughness: 0.8,
        });
        const seat = new Mesh(seatGeo, seatMat);
        seat.position.set(x, 0.15 + row * 0.15, z);
        this.arena.add(seat);

        // Simple crowd figure (small sphere on seat)
        if (Math.random() > 0.2) {
          const headGeo = new SphereGeometry(0.12, 6, 4);
          const headMat = new MeshStandardMaterial({
            color: new Color().setHSL(Math.random(), 0.5, 0.4),
          });
          const head = new Mesh(headGeo, headMat);
          head.position.set(x, 0.45 + row * 0.3, z);
          this.arena.add(head);
        }
      }
    }

    // Dust particles on ring (ambient)
    for (let i = 0; i < 20; i++) {
      const dustGeo = new SphereGeometry(0.02, 4, 3);
      const dustMat = new MeshStandardMaterial({ color: 0xccaa77, emissive: 0xccaa77, emissiveIntensity: 0.3, transparent: true, opacity: 0.4 });
      const dust = new Mesh(dustGeo, dustMat);
      const a = Math.random() * Math.PI * 2;
      const r2 = Math.random() * RING_RADIUS;
      dust.position.set(Math.cos(a) * r2, 0.4 + Math.random() * 0.3, Math.sin(a) * r2);
      this.arena.add(dust);
      this.dustParticles.push(dust);
    }
  }

  private createWrestler(isPlayer: boolean, color: number, weight: number, speed: number): Wrestler {
    const group = new Group();
    const scale = 0.8 + weight * 0.3;

    // Body (rotund torso)
    const bodyGeo = new SphereGeometry(0.35 * scale, 12, 10);
    bodyGeo.scale(1, 1.1, 0.9);
    const bodyMat = new MeshStandardMaterial({
      color: isPlayer ? 0xeebb88 : 0xddaa77,
      roughness: 0.6,
    });
    const body = new Mesh(bodyGeo, bodyMat);
    body.position.y = 0.5 * scale + 0.4;
    group.add(body);

    // Head
    const headGeo = new SphereGeometry(0.18 * scale, 10, 8);
    const headMat = new MeshStandardMaterial({ color: isPlayer ? 0xeebb88 : 0xddaa77, roughness: 0.6 });
    const head = new Mesh(headGeo, headMat);
    head.position.y = 0.9 * scale + 0.4;
    group.add(head);

    // Hair bun (topknot / chonmage)
    const bunGeo = new SphereGeometry(0.08 * scale, 8, 6);
    const bunMat = new MeshStandardMaterial({ color: 0x222222 });
    const bun = new Mesh(bunGeo, bunMat);
    bun.position.y = 1.05 * scale + 0.4;
    bun.position.z = -0.05;
    group.add(bun);

    // Belt (mawashi)
    const beltGeo = new TorusGeometry(0.36 * scale, 0.06, 8, 16);
    const beltMat = new MeshStandardMaterial({
      color: color,
      emissive: color,
      emissiveIntensity: 0.4,
    });
    const belt = new Mesh(beltGeo, beltMat);
    belt.rotation.x = Math.PI / 2;
    belt.position.y = 0.45 * scale + 0.4;
    group.add(belt);

    // Arms group
    const arms = new Group();
    arms.position.y = 0.6 * scale + 0.4;
    group.add(arms);

    // Left arm
    const armGeo = new CylinderGeometry(0.08 * scale, 0.06 * scale, 0.35 * scale, 6);
    const armMat = new MeshStandardMaterial({ color: isPlayer ? 0xeebb88 : 0xddaa77, roughness: 0.6 });
    const leftArm = new Mesh(armGeo, armMat);
    leftArm.position.set(-0.35 * scale, 0, 0);
    leftArm.rotation.z = Math.PI / 4;
    arms.add(leftArm);

    // Right arm
    const rightArm = new Mesh(armGeo.clone(), armMat.clone());
    rightArm.position.set(0.35 * scale, 0, 0);
    rightArm.rotation.z = -Math.PI / 4;
    arms.add(rightArm);

    // Legs
    const legGeo = new CylinderGeometry(0.12 * scale, 0.1 * scale, 0.3, 8);
    const legMat = new MeshStandardMaterial({ color: isPlayer ? 0xeebb88 : 0xddaa77, roughness: 0.6 });
    const leftLeg = new Mesh(legGeo, legMat);
    leftLeg.position.set(-0.15 * scale, 0.15 + 0.4, 0);
    group.add(leftLeg);
    const rightLeg = new Mesh(legGeo.clone(), legMat.clone());
    rightLeg.position.set(0.15 * scale, 0.15 + 0.4, 0);
    group.add(rightLeg);

    this.world.scene.add(group);

    return {
      group,
      body,
      head,
      belt,
      arms,
      leftArm,
      rightArm,
      pos: new Vector3(),
      vel: new Vector3(),
      facing: isPlayer ? 0 : Math.PI,
      pushCooldown: 0,
      grabCooldown: 0,
      dodgeCooldown: 0,
      chargeCooldown: 0,
      isCharging: false,
      chargeTime: 0,
      isGrabbing: false,
      grabTarget: false,
      stagger: 0,
      weight,
      speed,
      isPlayer,
      hp: 100,
      maxHp: 100,
      pushAnim: 0,
      grabAnim: 0,
      dodgeDir: new Vector3(),
      dodgeTime: 0,
      height: scale,
    };
  }

  private resetPositions() {
    this.player.pos.set(0, 0, 1.5);
    this.player.vel.set(0, 0, 0);
    this.player.facing = Math.PI;
    this.player.stagger = 0;
    this.player.isCharging = false;
    this.player.chargeTime = 0;
    this.player.isGrabbing = false;
    this.player.pushCooldown = 0;
    this.player.grabCooldown = 0;
    this.player.dodgeCooldown = 0;
    this.player.chargeCooldown = 0;
    this.player.dodgeTime = 0;

    this.opponent.pos.set(0, 0, -1.5);
    this.opponent.vel.set(0, 0, 0);
    this.opponent.facing = 0;
    this.opponent.stagger = 0;
    this.opponent.isCharging = false;
    this.opponent.chargeTime = 0;
    this.opponent.isGrabbing = false;
    this.opponent.pushCooldown = 0;
    this.opponent.grabCooldown = 0;
    this.opponent.dodgeCooldown = 0;
    this.opponent.chargeCooldown = 0;
    this.opponent.dodgeTime = 0;
  }

  private configureOpponent(def: OpponentDef) {
    const diffMult = [0.7, 1.0, 1.4][this.gameData.difficulty];
    const rankMult = 1 + this.gameData.currentRank * 0.08;
    this.opponent.weight = def.weight * rankMult;
    this.opponent.speed = def.speed * diffMult;

    // Update opponent visual
    const c = new Color(def.color);
    (this.opponent.belt.material as MeshStandardMaterial).color.copy(c);
    (this.opponent.belt.material as MeshStandardMaterial).emissive.copy(c);
  }

  startMatch() {
    const pool = [...OPPONENT_POOL];
    const rankIdx = Math.min(this.gameData.currentRank, RANKS.length - 1);
    // Pick opponent scaled to rank
    const idx = Math.min(rankIdx + Math.floor(Math.random() * 3), pool.length - 1);
    const oppDef = pool[idx];
    this.gameData.currentOpponent = oppDef;
    this.gameData.matchNumber++;
    this.gameData.roundTime = MATCH_TIME;
    this.gameData.matchResult = null;
    this.gameData.countdownTime = 3;
    this.gameData.isCountdown = true;

    this.configureOpponent(oppDef);
    this.resetPositions();
    this.clearFallAnimation();

    this.gameData.state = 'playing';
  }

  private clearFallAnimation() {
    if (this.fallGroup) {
      this.world.scene.remove(this.fallGroup);
      this.fallGroup = null;
    }
    this.fallingWrestler = null;
    this.fallAnim = 0;
    this.player.group.visible = true;
    this.opponent.group.visible = true;
  }

  update(delta: number, _time: number) {
    const dt = Math.min(delta, 0.05);

    if (this.gameData.state === 'playing') {
      if (this.gameData.isCountdown) {
        this.gameData.countdownTime -= dt;
        if (this.gameData.countdownTime <= 0) {
          this.gameData.isCountdown = false;
        }
      } else {
        this.updatePlayerInput(dt);
        this.updateAI(dt);
        this.updatePhysics(dt);
        this.checkRingOut();
        this.gameData.roundTime -= dt;
        if (this.gameData.roundTime <= 0) {
          this.endMatch('timeout');
        }
      }
    }

    // Update fall animation
    if (this.fallGroup) {
      this.fallAnim += dt;
      this.fallGroup.position.y -= dt * 3;
      this.fallGroup.rotation.x += dt * 4;
      this.fallGroup.rotation.z += dt * 2;
      if (this.fallAnim > 1.5) {
        this.clearFallAnimation();
      }
    }

    this.updateVisuals(dt, _time);
    this.updateParticles(dt);
    this.updateCamera(dt);
  }

  private updatePlayerInput(dt: number) {
    const input = this.world.input;
    const p = this.player;

    if (p.stagger > 0) {
      p.stagger -= dt;
      return;
    }
    if (p.dodgeTime > 0) return;

    // Movement
    let mx = 0, mz = 0;
    if (input.isKeyDown('KeyW') || input.isKeyDown('ArrowUp')) mz = -1;
    if (input.isKeyDown('KeyS') || input.isKeyDown('ArrowDown')) mz = 1;
    if (input.isKeyDown('KeyA') || input.isKeyDown('ArrowLeft')) mx = -1;
    if (input.isKeyDown('KeyD') || input.isKeyDown('ArrowRight')) mx = 1;

    // XR controller input
    const gamepad = input.getGamepad(InputComponent.RightGamepad);
    if (gamepad) {
      const axes = input.getAxesValues(InputComponent.RightGamepad);
      if (axes) {
        mx += axes.x;
        mz += axes.y;
      }
    }
    const leftGamepad = input.getGamepad(InputComponent.LeftGamepad);
    if (leftGamepad) {
      const lAxes = input.getAxesValues(InputComponent.LeftGamepad);
      if (lAxes) {
        mx += lAxes.x;
        mz += lAxes.y;
      }
    }

    const moveLen = Math.sqrt(mx * mx + mz * mz);
    if (moveLen > 0.1) {
      const speed = 3.5 * p.speed;
      p.vel.x += (mx / moveLen) * speed * dt;
      p.vel.z += (mz / moveLen) * speed * dt;
      p.facing = Math.atan2(this.opponent.pos.x - p.pos.x, this.opponent.pos.z - p.pos.z);
    }

    // Push (Space or Right Trigger)
    const triggerVal = input.getButtonValues(InputComponent.Trigger);
    const pushPressed = input.isKeyPressed('Space') || (triggerVal !== undefined && triggerVal > 0.5 && p.pushCooldown <= 0);
    if (pushPressed && p.pushCooldown <= 0) {
      this.performPush(p, this.opponent);
      p.pushCooldown = 0.5;
      this.gameData.totalPushes++;
    }

    // Grab (E or Grip)
    const gripVal = input.getButtonValues(InputComponent.Grip);
    const grabPressed = input.isKeyPressed('KeyE') || (gripVal !== undefined && gripVal > 0.5 && p.grabCooldown <= 0);
    if (grabPressed && p.grabCooldown <= 0) {
      this.performGrab(p, this.opponent);
      p.grabCooldown = 1.5;
      this.gameData.totalGrabs++;
    }

    // Dodge (Shift or Left Trigger)
    const leftTriggerVal = input.getButtonValues(InputComponent.LeftTrigger);
    const dodgePressed = input.isKeyPressed('ShiftLeft') || input.isKeyPressed('ShiftRight') ||
      (leftTriggerVal !== undefined && leftTriggerVal > 0.5 && p.dodgeCooldown <= 0);
    if (dodgePressed && p.dodgeCooldown <= 0) {
      this.performDodge(p, mx, mz);
      p.dodgeCooldown = 1.0;
      this.gameData.totalDodges++;
    }

    // Charge (hold Q or A button)
    const chargeHeld = input.isKeyDown('KeyQ');
    if (chargeHeld && p.chargeCooldown <= 0) {
      p.isCharging = true;
      p.chargeTime += dt;
    } else if (p.isCharging) {
      if (p.chargeTime > 0.3) {
        this.performCharge(p, this.opponent);
      }
      p.isCharging = false;
      p.chargeTime = 0;
      p.chargeCooldown = 2.0;
    }

    // Cooldowns
    p.pushCooldown = Math.max(0, p.pushCooldown - dt);
    p.grabCooldown = Math.max(0, p.grabCooldown - dt);
    p.dodgeCooldown = Math.max(0, p.dodgeCooldown - dt);
    p.chargeCooldown = Math.max(0, p.chargeCooldown - dt);
    p.pushAnim = Math.max(0, p.pushAnim - dt * 4);
    p.grabAnim = Math.max(0, p.grabAnim - dt * 3);
  }

  private performPush(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const dist = attacker.pos.distanceTo(target.pos);

    if (dist < 1.2) {
      // Check if opponent dodges
      if (!target.isPlayer && target.dodgeTime <= 0) {
        const opp = this.gameData.currentOpponent;
        if (opp && Math.random() < opp.technique * 0.3) {
          // Opponent dodges
          const perpDir = new Vector3(-dir.z, 0, dir.x);
          target.vel.add(perpDir.multiplyScalar(DODGE_SPEED * 0.5));
          this.spawnParticles(target.pos, 0x44ff44, 4);
          return;
        }
      }

      const force = PUSH_FORCE / Math.max(0.5, target.weight);
      target.vel.add(dir.multiplyScalar(force));
      target.stagger = 0.2;
      attacker.pushAnim = 1;
      this.spawnParticles(
        new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
        0xffaa44, 8
      );
      this.shakeIntensity = 0.05;
      this.shakeDecay = 3;

      if (this.gameData.sfxOn) {
        (this.getWorld() as any).__audioSystem?.playSFX('push');
      }
    }
  }

  private performGrab(attacker: Wrestler, target: Wrestler) {
    const dist = attacker.pos.distanceTo(target.pos);
    if (dist < 1.0) {
      // Grab and throw attempt
      const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
      const throwForce = (PUSH_FORCE * 1.5) / Math.max(0.5, target.weight);

      // Rotate direction by ±90 degrees for a throw
      const throwAngle = (Math.random() > 0.5 ? 1 : -1) * Math.PI * 0.4;
      const cosA = Math.cos(throwAngle), sinA = Math.sin(throwAngle);
      const throwDir = new Vector3(
        dir.x * cosA - dir.z * sinA,
        0,
        dir.x * sinA + dir.z * cosA
      );

      target.vel.add(throwDir.multiplyScalar(throwForce));
      target.stagger = 0.4;
      attacker.grabAnim = 1;
      this.spawnParticles(
        new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
        0xff44ff, 10
      );
      this.shakeIntensity = 0.08;
      this.shakeDecay = 3;

      if (this.gameData.sfxOn) {
        (this.getWorld() as any).__audioSystem?.playSFX('grab');
      }
    }
  }

  private performDodge(wrestler: Wrestler, mx: number, mz: number) {
    let dx = mx, dz = mz;
    if (Math.abs(dx) < 0.1 && Math.abs(dz) < 0.1) {
      // Dodge backward from opponent
      const away = new Vector3().subVectors(wrestler.pos, this.opponent.pos).normalize();
      dx = away.x;
      dz = away.z;
    }
    const len = Math.sqrt(dx * dx + dz * dz);
    if (len > 0) {
      wrestler.dodgeDir.set(dx / len, 0, dz / len);
    } else {
      wrestler.dodgeDir.set(0, 0, -1);
    }
    wrestler.dodgeTime = DODGE_DURATION;
    this.spawnParticles(wrestler.pos.clone().setY(0.5), 0x44ccff, 6);

    if (this.gameData.sfxOn) {
      (this.getWorld() as any).__audioSystem?.playSFX('dodge');
    }
  }

  private performCharge(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const chargeMultiplier = Math.min(attacker.chargeTime * 2, 3);
    const force = CHARGE_FORCE * chargeMultiplier / Math.max(0.5, target.weight);

    // Move attacker forward
    attacker.vel.add(dir.clone().multiplyScalar(5));

    const dist = attacker.pos.distanceTo(target.pos);
    if (dist < 2.0) {
      target.vel.add(dir.multiplyScalar(force));
      target.stagger = 0.5;
      this.spawnParticles(
        new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
        0xff8800, 15
      );
      this.shakeIntensity = 0.15;
      this.shakeDecay = 4;

      if (this.gameData.sfxOn) {
        (this.getWorld() as any).__audioSystem?.playSFX('charge');
      }
    }
  }

  private updateAI(dt: number) {
    const opp = this.opponent;
    const oppDef = this.gameData.currentOpponent;
    if (!oppDef || opp.stagger > 0 || opp.dodgeTime > 0) {
      opp.pushCooldown = Math.max(0, opp.pushCooldown - dt);
      opp.grabCooldown = Math.max(0, opp.grabCooldown - dt);
      opp.dodgeCooldown = Math.max(0, opp.dodgeCooldown - dt);
      opp.chargeCooldown = Math.max(0, opp.chargeCooldown - dt);
      return;
    }

    const toPlayer = new Vector3().subVectors(this.player.pos, opp.pos);
    const dist = toPlayer.length();
    toPlayer.normalize();

    // Face player
    opp.facing = Math.atan2(this.player.pos.x - opp.pos.x, this.player.pos.z - opp.pos.z);

    // Distance from center
    const oppDistFromCenter = Math.sqrt(opp.pos.x ** 2 + opp.pos.z ** 2);
    const playerDistFromCenter = Math.sqrt(this.player.pos.x ** 2 + this.player.pos.z ** 2);

    // Movement AI
    const moveSpeed = 2.5 * opp.speed;

    if (oppDistFromCenter > RING_RADIUS * 0.7) {
      // Too close to edge — move toward center
      const toCenter = new Vector3(-opp.pos.x, 0, -opp.pos.z).normalize();
      opp.vel.add(toCenter.multiplyScalar(moveSpeed * dt * 2));
    } else if (dist > 2.0) {
      // Approach player (based on aggression)
      if (Math.random() < oppDef.aggression) {
        opp.vel.add(toPlayer.clone().multiplyScalar(moveSpeed * dt));
      }
    } else if (dist > 1.0) {
      // Circle or approach
      if (Math.random() < oppDef.technique * 0.5) {
        // Circle strafe
        const perpDir = new Vector3(-toPlayer.z, 0, toPlayer.x);
        opp.vel.add(perpDir.multiplyScalar(moveSpeed * dt * 0.7));
      } else {
        opp.vel.add(toPlayer.clone().multiplyScalar(moveSpeed * dt * 0.8));
      }
    }

    // Attack decisions
    if (dist < 1.2 && opp.pushCooldown <= 0) {
      if (Math.random() < oppDef.aggression * 0.8 * dt * 3) {
        // Push
        if (Math.random() > oppDef.technique * 0.5 || opp.grabCooldown > 0) {
          this.performAIPush(opp, this.player);
          opp.pushCooldown = 0.6 / opp.speed;
        }
      }
    }

    if (dist < 1.0 && opp.grabCooldown <= 0) {
      if (Math.random() < oppDef.technique * 0.5 * dt * 2) {
        // Grab
        this.performAIGrab(opp, this.player);
        opp.grabCooldown = 2.0 / opp.speed;
      }
    }

    // Charge when player is near edge
    if (playerDistFromCenter > RING_RADIUS * 0.6 && dist < 2.5 && opp.chargeCooldown <= 0) {
      if (Math.random() < oppDef.aggression * dt) {
        this.performCharge(opp, this.player);
        opp.chargeCooldown = 3.0;
      }
    }

    // Dodge incoming charge
    if (this.player.isCharging && dist < 2.0 && opp.dodgeCooldown <= 0) {
      if (Math.random() < oppDef.technique * 0.6) {
        const perpDir = new Vector3(-toPlayer.z, 0, toPlayer.x);
        opp.vel.add(perpDir.multiplyScalar(DODGE_SPEED * 0.4));
        opp.dodgeCooldown = 1.5;
        this.spawnParticles(opp.pos.clone().setY(0.5), 0x44ff44, 4);
      }
    }

    opp.pushCooldown = Math.max(0, opp.pushCooldown - dt);
    opp.grabCooldown = Math.max(0, opp.grabCooldown - dt);
    opp.dodgeCooldown = Math.max(0, opp.dodgeCooldown - dt);
    opp.chargeCooldown = Math.max(0, opp.chargeCooldown - dt);
    opp.pushAnim = Math.max(0, opp.pushAnim - dt * 4);
    opp.grabAnim = Math.max(0, opp.grabAnim - dt * 3);
  }

  private performAIPush(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const force = PUSH_FORCE * 0.8 / Math.max(0.5, target.weight);
    target.vel.add(dir.multiplyScalar(force));
    target.stagger = 0.15;
    attacker.pushAnim = 1;
    this.spawnParticles(
      new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
      0xffaa44, 6
    );
    this.shakeIntensity = 0.04;
    this.shakeDecay = 3;

    if (this.gameData.sfxOn) {
      (this.getWorld() as any).__audioSystem?.playSFX('push');
    }
  }

  private performAIGrab(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const throwForce = (PUSH_FORCE * 1.2) / Math.max(0.5, target.weight);
    const throwAngle = (Math.random() > 0.5 ? 1 : -1) * Math.PI * 0.3;
    const cosA = Math.cos(throwAngle), sinA = Math.sin(throwAngle);
    const throwDir = new Vector3(dir.x * cosA - dir.z * sinA, 0, dir.x * sinA + dir.z * cosA);
    target.vel.add(throwDir.multiplyScalar(throwForce));
    target.stagger = 0.3;
    attacker.grabAnim = 1;
    this.spawnParticles(
      new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
      0xff44ff, 8
    );
    this.shakeIntensity = 0.06;
    this.shakeDecay = 3;

    if (this.gameData.sfxOn) {
      (this.getWorld() as any).__audioSystem?.playSFX('grab');
    }
  }

  private updatePhysics(dt: number) {
    for (const w of [this.player, this.opponent]) {
      // Dodge movement
      if (w.dodgeTime > 0) {
        w.pos.add(w.dodgeDir.clone().multiplyScalar(DODGE_SPEED * dt));
        w.dodgeTime -= dt;
        if (w.dodgeTime <= 0) w.dodgeTime = 0;
        continue;
      }

      // Apply velocity
      w.pos.add(w.vel.clone().multiplyScalar(dt));

      // Friction
      const frictionFactor = Math.max(0, 1 - FRICTION * dt);
      w.vel.multiplyScalar(frictionFactor);

      // Clamp small velocities
      if (w.vel.length() < 0.01) w.vel.set(0, 0, 0);
    }

    // Wrestler collision
    const diff = new Vector3().subVectors(this.player.pos, this.opponent.pos);
    const dist = diff.length();
    const minDist = 0.7;
    if (dist < minDist && dist > 0.01) {
      const overlap = minDist - dist;
      diff.normalize();
      this.player.pos.add(diff.clone().multiplyScalar(overlap * 0.5));
      this.opponent.pos.add(diff.clone().multiplyScalar(-overlap * 0.5));
    }
  }

  private checkRingOut() {
    const playerDist = Math.sqrt(this.player.pos.x ** 2 + this.player.pos.z ** 2);
    const oppDist = Math.sqrt(this.opponent.pos.x ** 2 + this.opponent.pos.z ** 2);

    if (playerDist > RING_RADIUS) {
      this.startFallAnimation('player');
      this.endMatch('loss');
    } else if (oppDist > RING_RADIUS) {
      this.startFallAnimation('opponent');
      this.endMatch('win');
    }
  }

  private startFallAnimation(who: 'player' | 'opponent') {
    const w = who === 'player' ? this.player : this.opponent;
    this.fallingWrestler = who;
    this.fallAnim = 0;

    // Create a simple falling clone
    this.fallGroup = new Group();
    const fallBody = new SphereGeometry(0.35 * w.height, 8, 6);
    const fallMat = new MeshStandardMaterial({ color: 0xddaa77 });
    const fallMesh = new Mesh(fallBody, fallMat);
    this.fallGroup.add(fallMesh);
    this.fallGroup.position.copy(w.group.position);
    this.world.scene.add(this.fallGroup);
    w.group.visible = false;

    // Big particle burst
    this.spawnParticles(w.pos.clone().setY(0.5), 0xff8800, 20);
    this.shakeIntensity = 0.2;
    this.shakeDecay = 5;

    if (this.gameData.sfxOn) {
      (this.getWorld() as any).__audioSystem?.playSFX('ringout');
    }
  }

  private endMatch(result: 'win' | 'loss' | 'timeout') {
    this.gameData.matchResult = result;
    if (result === 'win') {
      this.gameData.wins++;
      this.gameData.matchWins++;
      this.gameData.currentStreak++;
      this.gameData.totalRingOuts++;
      if (this.gameData.currentStreak > this.gameData.bestWinStreak) {
        this.gameData.bestWinStreak = this.gameData.currentStreak;
      }
      // Score: base + time bonus + rank bonus
      const timeBonus = Math.floor(this.gameData.roundTime * 10);
      const rankBonus = (this.gameData.currentRank + 1) * 100;
      this.gameData.score += 500 + timeBonus + rankBonus;
      // Rank up every 3 wins
      if (this.gameData.matchWins % 3 === 0 && this.gameData.currentRank < RANKS.length - 1) {
        this.gameData.currentRank++;
      }
    } else if (result === 'loss') {
      this.gameData.losses++;
      this.gameData.currentStreak = 0;
    } else {
      // Timeout — decide by position (closer to center wins)
      const pDist = Math.sqrt(this.player.pos.x ** 2 + this.player.pos.z ** 2);
      const oDist = Math.sqrt(this.opponent.pos.x ** 2 + this.opponent.pos.z ** 2);
      if (pDist < oDist) {
        this.gameData.matchResult = 'win';
        this.gameData.wins++;
        this.gameData.matchWins++;
        this.gameData.score += 300;
      } else {
        this.gameData.matchResult = 'loss';
        this.gameData.losses++;
        this.gameData.currentStreak = 0;
      }
    }

    this.saveStats();
    this.gameData.state = 'results';
  }

  private updateVisuals(dt: number, time: number) {
    // Update wrestler positions
    for (const w of [this.player, this.opponent]) {
      w.group.position.set(w.pos.x, 0.0, w.pos.z);
      w.group.rotation.y = w.facing;

      // Push animation — arms forward
      if (w.pushAnim > 0) {
        w.arms.rotation.x = -w.pushAnim * 0.8;
      } else if (w.grabAnim > 0) {
        w.arms.rotation.x = -w.grabAnim * 0.5;
        w.leftArm.rotation.z = Math.PI / 4 - w.grabAnim * 0.4;
        w.rightArm.rotation.z = -Math.PI / 4 + w.grabAnim * 0.4;
      } else {
        w.arms.rotation.x = 0;
        w.leftArm.rotation.z = Math.PI / 4;
        w.rightArm.rotation.z = -Math.PI / 4;
      }

      // Stagger wobble
      if (w.stagger > 0) {
        w.group.rotation.z = Math.sin(time * 20) * 0.1 * w.stagger;
      } else {
        w.group.rotation.z = 0;
      }

      // Charge glow
      if (w.isCharging) {
        const intensity = Math.min(w.chargeTime * 2, 1);
        (w.belt.material as MeshStandardMaterial).emissiveIntensity = 0.4 + intensity * 1.5;
        w.group.scale.set(1 + intensity * 0.1, 1, 1 + intensity * 0.1);
      } else {
        (w.belt.material as MeshStandardMaterial).emissiveIntensity = 0.4;
        w.group.scale.set(1, 1, 1);
      }

      // Bob animation
      w.body.position.y = 0.5 * w.height + 0.4 + Math.sin(time * 3 + (w.isPlayer ? 0 : 1)) * 0.02;
    }

    // Ring edge pulse
    const edgeMat = this.ringEdgeGlow.material as MeshStandardMaterial;
    edgeMat.emissiveIntensity = 0.3 + Math.sin(time * 2) * 0.15;

    // Update color scheme
    const scheme = COLOR_SCHEMES[this.gameData.colorScheme];
    edgeMat.color.set(scheme.accent);
    edgeMat.emissive.set(scheme.accent);

    // Lantern flicker
    for (const light of this.crowdLights) {
      light.intensity = 0.8 + Math.sin(time * 5 + light.position.x) * 0.2;
    }

    // Dust particles drift
    for (const dust of this.dustParticles) {
      dust.position.y = 0.4 + Math.sin(time * 1.5 + dust.position.x * 3) * 0.15;
      dust.position.x += Math.sin(time * 0.5 + dust.position.z) * dt * 0.1;
    }
  }

  private spawnParticles(pos: Vector3, color: number, count: number) {
    for (let i = 0; i < count; i++) {
      const geo = new SphereGeometry(0.04 + Math.random() * 0.04, 4, 3);
      const mat = new MeshStandardMaterial({
        color,
        emissive: color,
        emissiveIntensity: 0.8,
        transparent: true,
        opacity: 1,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.copy(pos);
      this.world.scene.add(mesh);

      const vel = new Vector3(
        (Math.random() - 0.5) * 4,
        Math.random() * 3 + 1,
        (Math.random() - 0.5) * 4
      );
      const life = 0.5 + Math.random() * 0.5;
      this.particles.push({ mesh, vel, life, maxLife: life });
    }
  }

  private updateParticles(dt: number) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.vel.y -= 8 * dt;
      p.mesh.position.add(p.vel.clone().multiplyScalar(dt));
      p.life -= dt;
      const t = p.life / p.maxLife;
      (p.mesh.material as MeshStandardMaterial).opacity = t;
      p.mesh.scale.setScalar(t);
      if (p.life <= 0) {
        this.world.scene.remove(p.mesh);
        p.mesh.geometry.dispose();
        (p.mesh.material as MeshStandardMaterial).dispose();
        this.particles.splice(i, 1);
      }
    }
  }

  private updateCamera(dt: number) {
    const cam = this.world.camera;

    // Elevated 3/4 view looking at ring center
    const targetPos = new Vector3(0, 6, 7);
    cam.position.lerp(targetPos, dt * 2);

    // Shake
    if (this.shakeIntensity > 0) {
      this.cameraOffset.set(
        (Math.random() - 0.5) * this.shakeIntensity,
        (Math.random() - 0.5) * this.shakeIntensity,
        (Math.random() - 0.5) * this.shakeIntensity
      );
      cam.position.add(this.cameraOffset);
      this.shakeIntensity *= Math.exp(-this.shakeDecay * dt);
      if (this.shakeIntensity < 0.001) this.shakeIntensity = 0;
    }

    cam.lookAt(0, 0.5, 0);
  }

  getGameData(): GameData {
    return this.gameData;
  }

  getRankName(): string {
    return RANKS[Math.min(this.gameData.currentRank, RANKS.length - 1)];
  }

  getOpponentName(): string {
    return this.gameData.currentOpponent?.name || 'UNKNOWN';
  }

  setDifficulty(d: number) { this.gameData.difficulty = d; }
  setColorScheme(c: number) { this.gameData.colorScheme = c; }
  setSfx(on: boolean) { this.gameData.sfxOn = on; }
  setMusic(on: boolean) { this.gameData.musicOn = on; }

  setState(s: GameState) {
    this.gameData.state = s;
  }

  resetCareer() {
    this.gameData.score = 0;
    this.gameData.wins = 0;
    this.gameData.losses = 0;
    this.gameData.currentRank = 0;
    this.gameData.matchWins = 0;
    this.gameData.matchNumber = 0;
    this.gameData.currentStreak = 0;
    this.gameData.totalPushes = 0;
    this.gameData.totalDodges = 0;
    this.gameData.totalGrabs = 0;
    this.gameData.totalRingOuts = 0;
    this.gameData.bestWinStreak = 0;
    this.saveStats();
  }
}
