{"content":"import { createSystem, UIKitMLAsset, World } from '@iwsdk/core';
import { SumoSystem } from './sumo-system.js';
import type { GameState } from './sumo-system.js';

export class UISystem extends createSystem({}) {
  private world!: World;
  private sumo!: SumoSystem;
  private menuPanel: UIKitMLAsset | null = null;
  private hudPanel: UIKitMLAsset | null = null;
  private pausePanel: UIKitMLAsset | null = null;
  private resultsPanel: UIKitMLAsset | null = null;
  private settingsPanel: UIKitMLAsset | null = null;
  private statsPanel: UIKitMLAsset | null = null;
  private initialized = false;
  private lastState: GameState = 'menu';
  private updateTimer = 0;

  init() {
    this.world = this.getWorld();
    this.sumo = this.world.getSystem(SumoSystem)!;

    this.menuPanel = this.world.getSceneObject<UIKitMLAsset>('menu-panel');
    this.hudPanel = this.world.getSceneObject<UIKitMLAsset>('hud-panel');
    this.pausePanel = this.world.getSceneObject<UIKitMLAsset>('pause-panel');
    this.resultsPanel = this.world.getSceneObject<UIKitMLAsset>('results-panel');
    this.settingsPanel = this.world.getSceneObject<UIKitMLAsset>('settings-panel');
    this.statsPanel = this.world.getSceneObject<UIKitMLAsset>('stats-panel');

    this.wireEvents();
    this.initialized = true;
    this.showOnly('menu');
  }

  private wireEvents() {
    // Menu
    if (this.menuPanel) {
      this.menuPanel.getElementById('btn-play')?.addEventListener('click', () => {
        this.sumo.startMatch();
        this.showOnly('hud');
      });
      this.menuPanel.getElementById('btn-settings')?.addEventListener('click', () => {
        this.sumo.setState('settings');
        this.showOnly('settings');
      });
      this.menuPanel.getElementById('btn-stats')?.addEventListener('click', () => {
        this.sumo.setState('stats');
        this.updateStatsPanel();
        this.showOnly('stats');
      });
    }

    // HUD — pause button
    if (this.hudPanel) {
      this.hudPanel.getElementById('btn-pause')?.addEventListener('click', () => {
        this.sumo.setState('paused');
        this.showOnly('pause');
      });
    }

    // Pause panel
    if (this.pausePanel) {
      this.pausePanel.getElementById('btn-resume')?.addEventListener('click', () => {
        this.sumo.setState('playing');
        this.showOnly('hud');
      });
      this.pausePanel.getElementById('btn-quit')?.addEventListener('click', () => {
        this.sumo.setState('menu');
        this.showOnly('menu');
      });
    }

    // Results panel
    if (this.resultsPanel) {
      this.resultsPanel.getElementById('btn-next')?.addEventListener('click', () => {
        this.sumo.startMatch();
        this.showOnly('hud');
      });
      this.resultsPanel.getElementById('btn-menu')?.addEventListener('click', () => {
        this.sumo.setState('menu');
        this.showOnly('menu');
      });
    }

    // Settings panel
    if (this.settingsPanel) {
      this.settingsPanel.getElementById('btn-easy')?.addEventListener('click', () => {
        this.sumo.setDifficulty(0);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-normal')?.addEventListener('click', () => {
        this.sumo.setDifficulty(1);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-hard')?.addEventListener('click', () => {
        this.sumo.setDifficulty(2);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-scheme0')?.addEventListener('click', () => {
        this.sumo.setColorScheme(0);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-scheme1')?.addEventListener('click', () => {
        this.sumo.setColorScheme(1);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-scheme2')?.addEventListener('click', () => {
        this.sumo.setColorScheme(2);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-scheme3')?.addEventListener('click', () => {
        this.sumo.setColorScheme(3);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-sfx')?.addEventListener('click', () => {
        const d = this.sumo.getGameData();
        this.sumo.setSfx(!d.sfxOn);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-music')?.addEventListener('click', () => {
        const d = this.sumo.getGameData();
        this.sumo.setMusic(!d.musicOn);
        this.updateSettingsPanel();
      });
      this.settingsPanel.getElementById('btn-back')?.addEventListener('click', () => {
        this.sumo.setState('menu');
        this.showOnly('menu');
      });
    }

    // Stats panel
    if (this.statsPanel) {
      this.statsPanel.getElementById('btn-back')?.addEventListener('click', () => {
        this.sumo.setState('menu');
        this.showOnly('menu');
      });
      this.statsPanel.getElementById('btn-reset')?.addEventListener('click', () => {
        this.sumo.resetCareer();
        this.updateStatsPanel();
      });
    }

    // Keyboard shortcuts
    const input = this.world.input;
    // ESC for pause
    // P for pause toggle (using isKeyPressed in update)
  }

  update(delta: number, _time: number) {
    if (!this.initialized) return;
    const data = this.sumo.getGameData();

    // Keyboard shortcuts
    const input = this.world.input;
    if (input.isKeyPressed('Escape') || input.isKeyPressed('KeyP')) {
      if (data.state === 'playing') {
        this.sumo.setState('paused');
        this.showOnly('pause');
      } else if (data.state === 'paused') {
        this.sumo.setState('playing');
        this.showOnly('hud');
      }
    }

    // State change detection
    if (data.state !== this.lastState) {
      this.lastState = data.state;
      switch (data.state) {
        case 'menu': this.showOnly('menu'); break;
        case 'playing': this.showOnly('hud'); break;
        case 'paused': this.showOnly('pause'); break;
        case 'results': this.updateResultsPanel(); this.showOnly('results'); break;
        case 'settings': this.updateSettingsPanel(); this.showOnly('settings'); break;
        case 'stats': this.updateStatsPanel(); this.showOnly('stats'); break;
      }
    }

    // HUD updates
    this.updateTimer += delta;
    if (data.state === 'playing' && this.updateTimer > 0.1) {
      this.updateTimer = 0;
      this.updateHUD(data);
    }
  }

  private showOnly(panel: string) {
    const panels = [
      { name: 'menu', obj: this.menuPanel },
      { name: 'hud', obj: this.hudPanel },
      { name: 'pause', obj: this.pausePanel },
      { name: 'results', obj: this.resultsPanel },
      { name: 'settings', obj: this.settingsPanel },
      { name: 'stats', obj: this.statsPanel },
    ];
    for (const p of panels) {
      if (p.obj) p.obj.visible = (p.name === panel);
    }
  }

  private updateHUD(data: ReturnType<SumoSystem['getGameData']>) {
    if (!this.hudPanel) return;

    if (data.isCountdown) {
      const countText = Math.ceil(data.countdownTime);
      this.hudPanel.getElementById('countdown')?.setProperties({ text: countText > 0 ? String(countText) : 'FIGHT!' });
      this.hudPanel.getElementById('countdown')?.setProperties({ visible: true } as any);
    } else {
      this.hudPanel.getElementById('countdown')?.setProperties({ text: '' });
    }

    this.hudPanel.getElementById('score')?.setProperties({ text: `Score: ${data.score}` });
    this.hudPanel.getElementById('time')?.setProperties({ text: `Time: ${Math.ceil(data.roundTime)}s` });
    this.hudPanel.getElementById('rank')?.setProperties({ text: `Rank: ${this.sumo.getRankName()}` });
    this.hudPanel.getElementById('opponent-name')?.setProperties({ text: `VS ${this.sumo.getOpponentName()}` });
    this.hudPanel.getElementById('match-num')?.setProperties({ text: `Match ${data.matchNumber}` });
    this.hudPanel.getElementById('streak')?.setProperties({ text: data.currentStreak > 1 ? `${data.currentStreak} Win Streak!` : '' });

    // Cooldown indicators
    const pushReady = data.isCountdown ? false : true;
    this.hudPanel.getElementById('push-cd')?.setProperties({ text: `Push: ${pushReady ? 'READY' : '...'}` });
  }

  private updateResultsPanel() {
    if (!this.resultsPanel) return;
    const data = this.sumo.getGameData();

    const resultText = data.matchResult === 'win' ? 'VICTORY!' : data.matchResult === 'loss' ? 'DEFEAT!' : 'TIME OUT';
    this.resultsPanel.getElementById('result-title')?.setProperties({ text: resultText });
    this.resultsPanel.getElementById('result-score')?.setProperties({ text: `Score: ${data.score}` });
    this.resultsPanel.getElementById('result-rank')?.setProperties({ text: `Rank: ${this.sumo.getRankName()}` });
    this.resultsPanel.getElementById('result-record')?.setProperties({ text: `Record: ${data.wins}W - ${data.losses}L` });
    this.resultsPanel.getElementById('result-streak')?.setProperties({ text: `Win Streak: ${data.currentStreak}` });
    this.resultsPanel.getElementById('result-opponent')?.setProperties({ text: `Opponent: ${this.sumo.getOpponentName()}` });
  }

  private updateSettingsPanel() {
    if (!this.settingsPanel) return;
    const data = this.sumo.getGameData();

    const diffs = ['Easy', 'Normal', 'Hard'];
    this.settingsPanel.getElementById('diff-label')?.setProperties({ text: `Difficulty: ${diffs[data.difficulty]}` });
    this.settingsPanel.getElementById('sfx-label')?.setProperties({ text: `SFX: ${data.sfxOn ? 'ON' : 'OFF'}` });
    this.settingsPanel.getElementById('music-label')?.setProperties({ text: `Music: ${data.musicOn ? 'ON' : 'OFF'}` });

    const schemes = ['Dohyo Classic', 'Neon Arena', 'Cherry Blossom', 'Thunder'];
    this.settingsPanel.getElementById('scheme-label')?.setProperties({ text: `Theme: ${schemes[data.colorScheme]}` });
  }

  private updateStatsPanel() {
    if (!this.statsPanel) return;
    const data = this.sumo.getGameData();

    this.statsPanel.getElementById('stat-wins')?.setProperties({ text: `Wins: ${data.wins}` });
    this.statsPanel.getElementById('stat-losses')?.setProperties({ text: `Losses: ${data.losses}` });
    this.statsPanel.getElementById('stat-rank')?.setProperties({ text: `Current Rank: ${this.sumo.getRankName()}` });
    this.statsPanel.getElementById('stat-pushes')?.setProperties({ text: `Total Pushes: ${data.totalPushes}` });
    this.statsPanel.getElementById('stat-grabs')?.setProperties({ text: `Total Grabs: ${data.totalGrabs}` });
    this.statsPanel.getElementById('stat-dodges')?.setProperties({ text: `Total Dodges: ${data.totalDodges}` });
    this.statsPanel.getElementById('stat-ringouts')?.setProperties({ text: `Ring Outs: ${data.totalRingOuts}` });
    this.statsPanel.getElementById('stat-streak')?.setProperties({ text: `Best Streak: ${data.bestWinStreak}` });
    this.statsPanel.getElementById('stat-score')?.setProperties({ text: `Total Score: ${data.score}` });
    this.statsPanel.getElementById('stat-ratio')?.setProperties({
      text: `Win Rate: ${data.wins + data.losses > 0 ? Math.round(data.wins / (data.wins + data.losses) * 100) : 0}%`
    });
  }
}
