{"content":"import { createSystem, World } from '@iwsdk/core';
import { SumoSystem } from './sumo-system.js';

export class AudioSystem extends createSystem({}) {
  private world!: World;
  private sumo!: SumoSystem;
  private audioCtx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private musicGain: GainNode | null = null;
  private musicOscs: OscillatorNode[] = [];
  private musicGains: GainNode[] = [];
  private musicPlaying = false;
  private musicBeat = 0;
  private beatTimer = 0;
  private bpm = 80;

  init() {
    this.world = this.getWorld();
    this.sumo = this.world.getSystem(SumoSystem)!;

    // Expose for SFX calls from SumoSystem
    (this.world as any).__audioSystem = this;

    try {
      this.audioCtx = new AudioContext();
      this.masterGain = this.audioCtx.createGain();
      this.masterGain.gain.value = 0.3;
      this.masterGain.connect(this.audioCtx.destination);

      this.musicGain = this.audioCtx.createGain();
      this.musicGain.gain.value = 0.15;
      this.musicGain.connect(this.masterGain);
    } catch (_) { /* no audio context */ }
  }

  private ensureCtx() {
    if (this.audioCtx && this.audioCtx.state === 'suspended') {
      this.audioCtx.resume().catch(() => {});
    }
  }

  playSFX(type: string) {
    if (!this.audioCtx || !this.masterGain) return;
    this.ensureCtx();

    const ctx = this.audioCtx;
    const now = ctx.currentTime;
    const sfxGain = ctx.createGain();
    sfxGain.connect(this.masterGain);

    switch (type) {
      case 'push': {
        // Meaty impact
        const osc = ctx.createOscillator();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(120, now);
        osc.frequency.exponentialRampToValueAtTime(40, now + 0.15);
        sfxGain.gain.setValueAtTime(0.5, now);
        sfxGain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);
        osc.connect(sfxGain);
        osc.start(now);
        osc.stop(now + 0.2);

        // Noise burst
        const bufferSize = ctx.sampleRate * 0.1;
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
          data[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize);
        }
        const noise = ctx.createBufferSource();
        noise.buffer = buffer;
        const noiseGain = ctx.createGain();
        noiseGain.gain.setValueAtTime(0.3, now);
        noiseGain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        noise.connect(noiseGain);
        noiseGain.connect(this.masterGain);
        noise.start(now);
        noise.stop(now + 0.1);
        break;
      }
      case 'grab': {
        // Grappling sound
        const osc1 = ctx.createOscillator();
        osc1.type = 'square';
        osc1.frequency.setValueAtTime(200, now);
        osc1.frequency.exponentialRampToValueAtTime(100, now + 0.3);
        sfxGain.gain.setValueAtTime(0.3, now);
        sfxGain.gain.exponentialRampToValueAtTime(0.01, now + 0.35);
        osc1.connect(sfxGain);
        osc1.start(now);
        osc1.stop(now + 0.35);

        const osc2 = ctx.createOscillator();
        osc2.type = 'triangle';
        osc2.frequency.setValueAtTime(300, now + 0.05);
        osc2.frequency.exponentialRampToValueAtTime(150, now + 0.25);
        const g2 = ctx.createGain();
        g2.gain.setValueAtTime(0.2, now + 0.05);
        g2.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
        osc2.connect(g2);
        g2.connect(this.masterGain);
        osc2.start(now + 0.05);
        osc2.stop(now + 0.3);
        break;
      }
      case 'dodge': {
        // Quick whoosh
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(800, now + 0.15);
        sfxGain.gain.setValueAtTime(0.25, now);
        sfxGain.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
        osc.connect(sfxGain);
        osc.start(now);
        osc.stop(now + 0.15);
        break;
      }
      case 'charge': {
        // Heavy slam
        const osc = ctx.createOscillator();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(80, now);
        osc.frequency.exponentialRampToValueAtTime(30, now + 0.4);
        sfxGain.gain.setValueAtTime(0.6, now);
        sfxGain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);
        osc.connect(sfxGain);
        osc.start(now);
        osc.stop(now + 0.4);

        // Sub bass
        const sub = ctx.createOscillator();
        sub.type = 'sine';
        sub.frequency.setValueAtTime(50, now);
        const subGain = ctx.createGain();
        subGain.gain.setValueAtTime(0.4, now);
        subGain.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
        sub.connect(subGain);
        subGain.connect(this.masterGain);
        sub.start(now);
        sub.stop(now + 0.5);
        break;
      }
      case 'ringout': {
        // Dramatic fall + crowd roar
        for (let i = 0; i < 4; i++) {
          const osc = ctx.createOscillator();
          osc.type = i % 2 === 0 ? 'sawtooth' : 'square';
          osc.frequency.setValueAtTime(200 - i * 30, now + i * 0.1);
          osc.frequency.exponentialRampToValueAtTime(50, now + 0.8);
          const g = ctx.createGain();
          g.gain.setValueAtTime(0.3, now + i * 0.1);
          g.gain.exponentialRampToValueAtTime(0.01, now + 0.8);
          osc.connect(g);
          g.connect(this.masterGain);
          osc.start(now + i * 0.1);
          osc.stop(now + 0.8);
        }

        // Crowd noise
        const bufferSize = Math.floor(ctx.sampleRate * 0.8);
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const bdata = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
          bdata[i] = (Math.random() * 2 - 1) * 0.5;
        }
        const crowd = ctx.createBufferSource();
        crowd.buffer = buffer;
        const crowdFilter = ctx.createBiquadFilter();
        crowdFilter.type = 'bandpass';
        crowdFilter.frequency.value = 800;
        crowdFilter.Q.value = 1;
        const crowdGain = ctx.createGain();
        crowdGain.gain.setValueAtTime(0.01, now + 0.3);
        crowdGain.gain.linearRampToValueAtTime(0.25, now + 0.6);
        crowdGain.gain.linearRampToValueAtTime(0.05, now + 1.5);
        crowd.connect(crowdFilter);
        crowdFilter.connect(crowdGain);
        crowdGain.connect(this.masterGain);
        crowd.start(now + 0.3);
        crowd.stop(now + 1.5);
        break;
      }
      case 'countdown': {
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.value = 440;
        sfxGain.gain.setValueAtTime(0.3, now);
        sfxGain.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
        osc.connect(sfxGain);
        osc.start(now);
        osc.stop(now + 0.15);
        break;
      }
      case 'fight': {
        // Fight bell
        for (let i = 0; i < 3; i++) {
          const osc = ctx.createOscillator();
          osc.type = 'sine';
          osc.frequency.value = 880 + i * 220;
          const g = ctx.createGain();
          g.gain.setValueAtTime(0.25, now);
          g.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
          osc.connect(g);
          g.connect(this.masterGain);
          osc.start(now);
          osc.stop(now + 0.5);
        }
        break;
      }
    }
  }

  update(delta: number, _time: number) {
    if (!this.audioCtx || !this.musicGain) return;
    const data = this.sumo.getGameData();

    // Music toggle
    if (data.state === 'playing' && data.musicOn && !data.isCountdown) {
      if (!this.musicPlaying) {
        this.startMusic();
      }
      this.updateMusic(delta);
    } else if (this.musicPlaying) {
      this.stopMusic();
    }

    // SFX toggle
    if (this.masterGain) {
      this.masterGain.gain.value = data.sfxOn ? 0.3 : 0;
    }
  }

  private startMusic() {
    if (!this.audioCtx || !this.musicGain) return;
    this.musicPlaying = true;
    this.musicBeat = 0;
    this.beatTimer = 0;
  }

  private stopMusic() {
    this.musicPlaying = false;
    for (const osc of this.musicOscs) {
      try { osc.stop(); } catch (_) { /* already stopped */ }
    }
    this.musicOscs = [];
    this.musicGains = [];
  }

  private updateMusic(delta: number) {
    if (!this.audioCtx || !this.musicGain) return;
    const ctx = this.audioCtx;
    const now = ctx.currentTime;
    const beatInterval = 60 / this.bpm;

    this.beatTimer += delta;
    if (this.beatTimer >= beatInterval) {
      this.beatTimer -= beatInterval;
      this.musicBeat++;

      // Taiko-style drum pattern
      const pattern = this.musicBeat % 8;

      // Big drum (don) — beats 0, 4
      if (pattern === 0 || pattern === 4) {
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(80, now);
        osc.frequency.exponentialRampToValueAtTime(40, now + 0.3);
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.4, now);
        g.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
        osc.connect(g);
        g.connect(this.musicGain);
        osc.start(now);
        osc.stop(now + 0.3);

        // Attack transient
        const click = ctx.createOscillator();
        click.type = 'square';
        click.frequency.value = 200;
        const cg = ctx.createGain();
        cg.gain.setValueAtTime(0.2, now);
        cg.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
        click.connect(cg);
        cg.connect(this.musicGain);
        click.start(now);
        click.stop(now + 0.05);
      }

      // Small drum (ka) — beats 2, 6
      if (pattern === 2 || pattern === 6) {
        const osc = ctx.createOscillator();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(300, now);
        osc.frequency.exponentialRampToValueAtTime(150, now + 0.1);
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.25, now);
        g.gain.exponentialRampToValueAtTime(0.01, now + 0.12);
        osc.connect(g);
        g.connect(this.musicGain);
        osc.start(now);
        osc.stop(now + 0.12);
      }

      // Rim hit — beats 1, 3, 5, 7
      if (pattern % 2 === 1) {
        const bufferSize = Math.floor(ctx.sampleRate * 0.05);
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const d = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
          d[i] = (Math.random() * 2 - 1) * (1 - i / bufferSize) * 0.5;
        }
        const noise = ctx.createBufferSource();
        noise.buffer = buffer;
        const filter = ctx.createBiquadFilter();
        filter.type = 'highpass';
        filter.frequency.value = 2000;
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.15, now);
        g.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
        noise.connect(filter);
        filter.connect(g);
        g.connect(this.musicGain);
        noise.start(now);
        noise.stop(now + 0.05);
      }

      // Shamisen-style melody every 4 bars
      if (this.musicBeat % 32 < 8) {
        const scale = [220, 246.94, 293.66, 329.63, 440, 493.88, 587.33];
        const noteIdx = pattern % scale.length;
        const osc = ctx.createOscillator();
        osc.type = 'sawtooth';
        osc.frequency.value = scale[noteIdx];
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.08, now);
        g.gain.exponentialRampToValueAtTime(0.01, now + beatInterval * 0.8);
        osc.connect(g);
        g.connect(this.musicGain);
        osc.start(now);
        osc.stop(now + beatInterval * 0.8);
      }

      // Bass drone
      if (pattern === 0) {
        const bassNotes = [55, 55, 65.41, 55];
        const barIdx = Math.floor(this.musicBeat / 8) % bassNotes.length;
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.value = bassNotes[barIdx];
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.15, now);
        g.gain.linearRampToValueAtTime(0.12, now + beatInterval * 4);
        g.gain.exponentialRampToValueAtTime(0.01, now + beatInterval * 7);
        osc.connect(g);
        g.connect(this.musicGain);
        osc.start(now);
        osc.stop(now + beatInterval * 7);
      }
    }
  }
}
