{"content":"import {
  createSystem,
  InputComponent,
  UIKitMLAsset,
} from '@iwsdk/core';
import {
  Vector3,
  Mesh,
  MeshStandardMaterial,
  CylinderGeometry,
  RingGeometry,
  SphereGeometry,
  BoxGeometry,
  Group,
  PointLight,
  Color,
  DoubleSide,
  PlaneGeometry,
  AmbientLight,
  DirectionalLight,
  TorusGeometry,
} from 'three';

// === Game State ===
export type GameState = 'menu' | 'playing' | 'paused' | 'results' | 'settings' | 'stats';
export type Rank = 'Jonokuchi' | 'Jonidan' | 'Sandanme' | 'Makushita' | 'Juryo' | 'Maegashira' | 'Komusubi' | 'Sekiwake' | 'Ozeki' | 'Yokozuna';

const RANKS: Rank[] = ['Jonokuchi', 'Jonidan', 'Sandanme', 'Makushita', 'Juryo', 'Maegashira', 'Komusubi', 'Sekiwake', 'Ozeki', 'Yokozuna'];

interface OpponentDef {
  name: string;
  weight: number;
  speed: number;
  aggression: number;
  technique: number;
  color: number;
}

const OPPONENT_POOL: OpponentDef[] = [
  { name: 'TARO', weight: 0.7, speed: 1.2, aggression: 0.3, technique: 0.2, color: 0x44aaff },
  { name: 'KENJI', weight: 1.0, speed: 1.0, aggression: 0.5, technique: 0.3, color: 0xff6644 },
  { name: 'HIRO', weight: 1.3, speed: 0.8, aggression: 0.6, technique: 0.4, color: 0x44ff88 },
  { name: 'DAICHI', weight: 1.5, speed: 0.7, aggression: 0.7, technique: 0.5, color: 0xffaa22 },
  { name: 'RYU', weight: 0.8, speed: 1.3, aggression: 0.4, technique: 0.6, color: 0xaa44ff },
  { name: 'TAKESHI', weight: 1.8, speed: 0.6, aggression: 0.8, technique: 0.3, color: 0xff4444 },
  { name: 'YOSHI', weight: 0.6, speed: 1.4, aggression: 0.2, technique: 0.7, color: 0x44ffff },
  { name: 'MASA', weight: 1.1, speed: 0.9, aggression: 0.6, technique: 0.5, color: 0xffff44 },
  { name: 'GORO', weight: 2.0, speed: 0.5, aggression: 0.9, technique: 0.2, color: 0xff2222 },
  { name: 'SHIN', weight: 0.9, speed: 1.1, aggression: 0.5, technique: 0.8, color: 0x88ff44 },
  { name: 'KENZO', weight: 1.4, speed: 0.8, aggression: 0.7, technique: 0.6, color: 0xff8844 },
  { name: 'RAIDEN', weight: 1.6, speed: 0.9, aggression: 0.8, technique: 0.7, color: 0xff00ff },
];

interface Wrestler {
  group: Group;
  body: Mesh;
  head: Mesh;
  belt: Mesh;
  arms: Group;
  leftArm: Mesh;
  rightArm: Mesh;
  pos: Vector3;
  vel: Vector3;
  facing: number;
  pushCooldown: number;
  grabCooldown: number;
  dodgeCooldown: number;
  chargeCooldown: number;
  isCharging: boolean;
  chargeTime: number;
  isGrabbing: boolean;
  grabTarget: boolean;
  stagger: number;
  weightVal: number;
  speedVal: number;
  isPlayerWrestler: boolean;
  pushAnim: number;
  grabAnim: number;
  dodgeDir: Vector3;
  dodgeTime: number;
  heightScale: number;
}

interface Particle {
  mesh: Mesh;
  vel: Vector3;
  life: number;
  maxLife: number;
}

export interface GameData {
  state: GameState;
  score: number;
  wins: number;
  losses: number;
  currentRank: number;
  matchWins: number;
  totalPushes: number;
  totalDodges: number;
  totalGrabs: number;
  totalRingOuts: number;
  bestWinStreak: number;
  currentStreak: number;
  currentOpponent: OpponentDef | null;
  matchNumber: number;
  roundTime: number;
  difficulty: number;
  colorScheme: number;
  sfxOn: boolean;
  musicOn: boolean;
  matchResult: 'win' | 'loss' | 'timeout' | null;
  countdownTime: number;
  isCountdown: boolean;
}

const COLOR_SCHEMES = [
  { name: 'Dohyo Classic', bg: 0x1a0a00, ring: 0xcc9944, accent: 0xffdd66, floor: 0x332211 },
  { name: 'Neon Arena', bg: 0x000820, ring: 0x0066ff, accent: 0x00ccff, floor: 0x0a0a2a },
  { name: 'Cherry Blossom', bg: 0x1a0010, ring: 0xff6699, accent: 0xff99cc, floor: 0x2a0a1a },
  { name: 'Thunder', bg: 0x0a0a00, ring: 0xffaa00, accent: 0xffcc44, floor: 0x1a1a0a },
];

const RING_RADIUS = 3.5;
const PUSH_FORCE = 6.0;
const CHARGE_FORCE = 10.0;
const DODGE_SPEED = 8.0;
const DODGE_DURATION = 0.25;
const FRICTION = 4.0;
const MATCH_TIME = 60;

export class SumoSystem extends createSystem({}) {
  private playerW!: Wrestler;
  private opponentW!: Wrestler;
  private arena!: Group;
  private particles: Particle[] = [];
  private gameData!: GameData;
  private ringEdgeGlow!: Mesh;
  private crowdLights: PointLight[] = [];
  private shakeIntensity = 0;
  private shakeDecay = 0;
  private cameraOffset = new Vector3();
  private dustParticles: Mesh[] = [];
  private fallGroup: Group | null = null;
  private fallAnim = 0;
  private fallingWrestler: 'player' | 'opponent' | null = null;
  audioSystemRef: { playSFX: (type: string) => void } | null = null;

  init() {
    this.gameData = {
      state: 'menu',
      score: 0,
      wins: 0,
      losses: 0,
      currentRank: 0,
      matchWins: 0,
      totalPushes: 0,
      totalDodges: 0,
      totalGrabs: 0,
      totalRingOuts: 0,
      bestWinStreak: 0,
      currentStreak: 0,
      currentOpponent: null,
      matchNumber: 0,
      roundTime: MATCH_TIME,
      difficulty: 1,
      colorScheme: 0,
      sfxOn: true,
      musicOn: true,
      matchResult: null,
      countdownTime: 3,
      isCountdown: false,
    };

    this.loadStats();
    this.buildArena();
    this.playerW = this.createWrestler(true, 0x00aaff, 1.0, 1.0);
    this.opponentW = this.createWrestler(false, 0xff4422, 1.0, 1.0);
    this.resetPositions();
  }

  private loadStats() {
    try {
      const saved = localStorage.getItem('neon-sumo-stats');
      if (saved) {
        const s = JSON.parse(saved);
        this.gameData.wins = s.wins || 0;
        this.gameData.losses = s.losses || 0;
        this.gameData.currentRank = s.currentRank || 0;
        this.gameData.totalPushes = s.totalPushes || 0;
        this.gameData.totalDodges = s.totalDodges || 0;
        this.gameData.totalGrabs = s.totalGrabs || 0;
        this.gameData.totalRingOuts = s.totalRingOuts || 0;
        this.gameData.bestWinStreak = s.bestWinStreak || 0;
      }
    } catch (_) { /* ignore */ }
  }

  private saveStats() {
    try {
      localStorage.setItem('neon-sumo-stats', JSON.stringify({
        wins: this.gameData.wins,
        losses: this.gameData.losses,
        currentRank: this.gameData.currentRank,
        totalPushes: this.gameData.totalPushes,
        totalDodges: this.gameData.totalDodges,
        totalGrabs: this.gameData.totalGrabs,
        totalRingOuts: this.gameData.totalRingOuts,
        bestWinStreak: this.gameData.bestWinStreak,
      }));
    } catch (_) { /* ignore */ }
  }

  private buildArena() {
    this.arena = new Group();
    this.scene.add(this.arena);

    const ambient = new AmbientLight(0x404060, 0.6);
    this.scene.add(ambient);
    const dirLight = new DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 5);
    this.scene.add(dirLight);

    // Ground plane
    const groundGeo = new PlaneGeometry(30, 30);
    const groundMat = new MeshStandardMaterial({ color: 0x1a1a2e, roughness: 0.9 });
    const ground = new Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.05;
    this.arena.add(ground);

    // Ring platform (raised dohyo)
    const platformGeo = new CylinderGeometry(RING_RADIUS + 0.8, RING_RADIUS + 1.2, 0.4, 48);
    const platformMat = new MeshStandardMaterial({ color: 0x886633, roughness: 0.7 });
    const platform = new Mesh(platformGeo, platformMat);
    platform.position.y = 0.15;
    this.arena.add(platform);

    // Ring surface
    const ringGeo = new CylinderGeometry(RING_RADIUS + 0.3, RING_RADIUS + 0.3, 0.05, 48);
    const ringMat = new MeshStandardMaterial({ color: 0xcc9944, roughness: 0.5 });
    const ringSurface = new Mesh(ringGeo, ringMat);
    ringSurface.position.y = 0.36;
    this.arena.add(ringSurface);

    // Ring boundary line (tawara)
    const edgeGeo = new TorusGeometry(RING_RADIUS, 0.08, 8, 64);
    const edgeMat = new MeshStandardMaterial({ color: 0xffdd66, emissive: 0xffdd66, emissiveIntensity: 0.5 });
    this.ringEdgeGlow = new Mesh(edgeGeo, edgeMat);
    this.ringEdgeGlow.rotation.x = -Math.PI / 2;
    this.ringEdgeGlow.position.y = 0.4;
    this.arena.add(this.ringEdgeGlow);

    // Corner posts (4 pillars with lanterns)
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const px = Math.cos(angle) * (RING_RADIUS + 1.5);
      const pz = Math.sin(angle) * (RING_RADIUS + 1.5);

      const pillarGeo = new CylinderGeometry(0.12, 0.15, 2.5, 8);
      const pillarMat = new MeshStandardMaterial({ color: 0xcc2222, emissive: 0xcc2222, emissiveIntensity: 0.3 });
      const pillar = new Mesh(pillarGeo, pillarMat);
      pillar.position.set(px, 1.25, pz);
      this.arena.add(pillar);

      const lanternGeo = new BoxGeometry(0.3, 0.4, 0.3);
      const lanternMat = new MeshStandardMaterial({ color: 0xff6600, emissive: 0xff6600, emissiveIntensity: 0.6 });
      const lantern = new Mesh(lanternGeo, lanternMat);
      lantern.position.set(px, 2.6, pz);
      this.arena.add(lantern);

      const light = new PointLight(0xff8844, 1.0, 8);
      light.position.set(px, 2.8, pz);
      this.arena.add(light);
      this.crowdLights.push(light);
    }

    // Ropes between pillars
    for (let i = 0; i < 4; i++) {
      const angle1 = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const angle2 = ((i + 1) / 4) * Math.PI * 2 + Math.PI / 4;
      const r = RING_RADIUS + 1.5;
      const x1 = Math.cos(angle1) * r, z1 = Math.sin(angle1) * r;
      const x2 = Math.cos(angle2) * r, z2 = Math.sin(angle2) * r;
      const ropeLen = Math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2);
      const ropeGeo = new CylinderGeometry(0.04, 0.04, ropeLen, 6);
      const ropeMat = new MeshStandardMaterial({ color: 0xffcc00, emissive: 0xffcc00, emissiveIntensity: 0.2 });
      const rope = new Mesh(ropeGeo, ropeMat);
      rope.position.set((x1 + x2) / 2, 2.5, (z1 + z2) / 2);
      rope.lookAt(x2, 2.5, z2);
      rope.rotateZ(Math.PI / 2);
      this.arena.add(rope);
    }

    // Spectator stands
    for (let row = 0; row < 3; row++) {
      const r = RING_RADIUS + 3 + row * 1.5;
      const count = 16 + row * 8;
      for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const x = Math.cos(angle) * r;
        const z = Math.sin(angle) * r;

        const seatGeo = new BoxGeometry(0.4, 0.3 + row * 0.3, 0.4);
        const seatMat = new MeshStandardMaterial({
          color: new Color().setHSL(Math.random() * 0.1 + 0.55, 0.3, 0.15),
          roughness: 0.8,
        });
        const seat = new Mesh(seatGeo, seatMat);
        seat.position.set(x, 0.15 + row * 0.15, z);
        this.arena.add(seat);

        if (Math.random() > 0.2) {
          const headGeo = new SphereGeometry(0.12, 6, 4);
          const headMat = new MeshStandardMaterial({
            color: new Color().setHSL(Math.random(), 0.5, 0.4),
          });
          const head = new Mesh(headGeo, headMat);
          head.position.set(x, 0.45 + row * 0.3, z);
          this.arena.add(head);
        }
      }
    }

    // Dust particles
    for (let i = 0; i < 20; i++) {
      const dustGeo = new SphereGeometry(0.02, 4, 3);
      const dustMat = new MeshStandardMaterial({ color: 0xccaa77, emissive: 0xccaa77, emissiveIntensity: 0.3, transparent: true, opacity: 0.4 });
      const dust = new Mesh(dustGeo, dustMat);
      const a = Math.random() * Math.PI * 2;
      const r2 = Math.random() * RING_RADIUS;
      dust.position.set(Math.cos(a) * r2, 0.4 + Math.random() * 0.3, Math.sin(a) * r2);
      this.arena.add(dust);
      this.dustParticles.push(dust);
    }
  }

  private createWrestler(isPlayer: boolean, color: number, weight: number, speed: number): Wrestler {
    const group = new Group();
    const scale = 0.8 + weight * 0.3;

    // Body
    const bodyGeo = new SphereGeometry(0.35 * scale, 12, 10);
    bodyGeo.scale(1, 1.1, 0.9);
    const bodyMat = new MeshStandardMaterial({
      color: isPlayer ? 0xeebb88 : 0xddaa77,
      roughness: 0.6,
    });
    const body = new Mesh(bodyGeo, bodyMat);
    body.position.y = 0.5 * scale + 0.4;
    group.add(body);

    // Head
    const headGeo = new SphereGeometry(0.18 * scale, 10, 8);
    const headMat = new MeshStandardMaterial({ color: isPlayer ? 0xeebb88 : 0xddaa77, roughness: 0.6 });
    const head = new Mesh(headGeo, headMat);
    head.position.y = 0.9 * scale + 0.4;
    group.add(head);

    // Topknot (chonmage)
    const bunGeo = new SphereGeometry(0.08 * scale, 8, 6);
    const bunMat = new MeshStandardMaterial({ color: 0x222222 });
    const bun = new Mesh(bunGeo, bunMat);
    bun.position.y = 1.05 * scale + 0.4;
    bun.position.z = -0.05;
    group.add(bun);

    // Belt (mawashi)
    const beltGeo = new TorusGeometry(0.36 * scale, 0.06, 8, 16);
    const beltMat = new MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.4 });
    const belt = new Mesh(beltGeo, beltMat);
    belt.rotation.x = Math.PI / 2;
    belt.position.y = 0.45 * scale + 0.4;
    group.add(belt);

    // Arms
    const arms = new Group();
    arms.position.y = 0.6 * scale + 0.4;
    group.add(arms);

    const armGeo = new CylinderGeometry(0.08 * scale, 0.06 * scale, 0.35 * scale, 6);
    const armMat = new MeshStandardMaterial({ color: isPlayer ? 0xeebb88 : 0xddaa77, roughness: 0.6 });
    const leftArm = new Mesh(armGeo, armMat);
    leftArm.position.set(-0.35 * scale, 0, 0);
    leftArm.rotation.z = Math.PI / 4;
    arms.add(leftArm);

    const rightArm = new Mesh(armGeo.clone(), armMat.clone());
    rightArm.position.set(0.35 * scale, 0, 0);
    rightArm.rotation.z = -Math.PI / 4;
    arms.add(rightArm);

    // Legs
    const legGeo = new CylinderGeometry(0.12 * scale, 0.1 * scale, 0.3, 8);
    const legMat = new MeshStandardMaterial({ color: isPlayer ? 0xeebb88 : 0xddaa77, roughness: 0.6 });
    const leftLeg = new Mesh(legGeo, legMat);
    leftLeg.position.set(-0.15 * scale, 0.15 + 0.4, 0);
    group.add(leftLeg);
    const rightLeg = new Mesh(legGeo.clone(), legMat.clone());
    rightLeg.position.set(0.15 * scale, 0.15 + 0.4, 0);
    group.add(rightLeg);

    this.scene.add(group);

    return {
      group,
      body,
      head,
      belt,
      arms,
      leftArm,
      rightArm,
      pos: new Vector3(),
      vel: new Vector3(),
      facing: isPlayer ? 0 : Math.PI,
      pushCooldown: 0,
      grabCooldown: 0,
      dodgeCooldown: 0,
      chargeCooldown: 0,
      isCharging: false,
      chargeTime: 0,
      isGrabbing: false,
      grabTarget: false,
      stagger: 0,
      weightVal: weight,
      speedVal: speed,
      isPlayerWrestler: isPlayer,
      pushAnim: 0,
      grabAnim: 0,
      dodgeDir: new Vector3(),
      dodgeTime: 0,
      heightScale: scale,
    };
  }

  private resetPositions() {
    this.playerW.pos.set(0, 0, 1.5);
    this.playerW.vel.set(0, 0, 0);
    this.playerW.facing = Math.PI;
    this.playerW.stagger = 0;
    this.playerW.isCharging = false;
    this.playerW.chargeTime = 0;
    this.playerW.isGrabbing = false;
    this.playerW.pushCooldown = 0;
    this.playerW.grabCooldown = 0;
    this.playerW.dodgeCooldown = 0;
    this.playerW.chargeCooldown = 0;
    this.playerW.dodgeTime = 0;

    this.opponentW.pos.set(0, 0, -1.5);
    this.opponentW.vel.set(0, 0, 0);
    this.opponentW.facing = 0;
    this.opponentW.stagger = 0;
    this.opponentW.isCharging = false;
    this.opponentW.chargeTime = 0;
    this.opponentW.isGrabbing = false;
    this.opponentW.pushCooldown = 0;
    this.opponentW.grabCooldown = 0;
    this.opponentW.dodgeCooldown = 0;
    this.opponentW.chargeCooldown = 0;
    this.opponentW.dodgeTime = 0;
  }

  private configureOpponent(def: OpponentDef) {
    const diffMult = [0.7, 1.0, 1.4][this.gameData.difficulty];
    const rankMult = 1 + this.gameData.currentRank * 0.08;
    this.opponentW.weightVal = def.weight * rankMult;
    this.opponentW.speedVal = def.speed * diffMult;

    const c = new Color(def.color);
    (this.opponentW.belt.material as MeshStandardMaterial).color.copy(c);
    (this.opponentW.belt.material as MeshStandardMaterial).emissive.copy(c);
  }

  startMatch() {
    const pool = [...OPPONENT_POOL];
    const rankIdx = Math.min(this.gameData.currentRank, RANKS.length - 1);
    const idx = Math.min(rankIdx + Math.floor(Math.random() * 3), pool.length - 1);
    const oppDef = pool[idx];
    this.gameData.currentOpponent = oppDef;
    this.gameData.matchNumber++;
    this.gameData.roundTime = MATCH_TIME;
    this.gameData.matchResult = null;
    this.gameData.countdownTime = 3;
    this.gameData.isCountdown = true;

    this.configureOpponent(oppDef);
    this.resetPositions();
    this.clearFallAnimation();
    this.gameData.state = 'playing';
  }

  private clearFallAnimation() {
    if (this.fallGroup) {
      this.scene.remove(this.fallGroup);
      this.fallGroup = null;
    }
    this.fallingWrestler = null;
    this.fallAnim = 0;
    this.playerW.group.visible = true;
    this.opponentW.group.visible = true;
  }

  update(delta: number, time: number) {
    const dt = Math.min(delta, 0.05);

    if (this.gameData.state === 'playing') {
      if (this.gameData.isCountdown) {
        this.gameData.countdownTime -= dt;
        if (this.gameData.countdownTime <= 0) {
          this.gameData.isCountdown = false;
        }
      } else {
        this.updatePlayerInput(dt);
        this.updateAI(dt);
        this.updatePhysics(dt);
        this.checkRingOut();
        this.gameData.roundTime -= dt;
        if (this.gameData.roundTime <= 0) {
          this.endMatch('timeout');
        }
      }
    }

    // Fall animation
    if (this.fallGroup) {
      this.fallAnim += dt;
      this.fallGroup.position.y -= dt * 3;
      this.fallGroup.rotation.x += dt * 4;
      this.fallGroup.rotation.z += dt * 2;
      if (this.fallAnim > 1.5) {
        this.clearFallAnimation();
      }
    }

    this.updateVisuals(dt, time);
    this.updateParticles(dt);
    this.updateCamera(dt);
  }

  private updatePlayerInput(dt: number) {
    const kb = this.input.keyboard;
    const p = this.playerW;

    if (p.stagger > 0) {
      p.stagger -= dt;
      return;
    }
    if (p.dodgeTime > 0) return;

    // Movement via keyboard
    let mx = 0, mz = 0;
    if (kb.getKeyPressed('KeyW') || kb.getKeyPressed('ArrowUp')) mz = -1;
    if (kb.getKeyPressed('KeyS') || kb.getKeyPressed('ArrowDown')) mz = 1;
    if (kb.getKeyPressed('KeyA') || kb.getKeyPressed('ArrowLeft')) mx = -1;
    if (kb.getKeyPressed('KeyD') || kb.getKeyPressed('ArrowRight')) mx = 1;

    // XR controller input via gamepads
    const xrGamepads = this.input.xr.gamepads;
    const leftGP = xrGamepads?.left;
    const rightGP = xrGamepads?.right;
    if (leftGP) {
      const axes = leftGP.getAxesValues(InputComponent.Thumbstick);
      if (axes) { mx += axes.x; mz += axes.y; }
    }
    if (rightGP) {
      const axes = rightGP.getAxesValues(InputComponent.Thumbstick);
      if (axes) { mx += axes.x; mz += axes.y; }
    }

    const moveLen = Math.sqrt(mx * mx + mz * mz);
    if (moveLen > 0.1) {
      const speed = 3.5 * p.speedVal;
      p.vel.x += (mx / moveLen) * speed * dt;
      p.vel.z += (mz / moveLen) * speed * dt;
      p.facing = Math.atan2(this.opponentW.pos.x - p.pos.x, this.opponentW.pos.z - p.pos.z);
    }

    // Push (Space or Right Trigger)
    const rightTriggerDown = rightGP ? rightGP.getButtonDown(InputComponent.Trigger) : false;
    const pushPressed = kb.getKeyDown('Space') || rightTriggerDown;
    if (pushPressed && p.pushCooldown <= 0) {
      this.performPush(p, this.opponentW);
      p.pushCooldown = 0.5;
      this.gameData.totalPushes++;
    }

    // Grab (E or Right Squeeze/Grip)
    const rightGripDown = rightGP ? rightGP.getButtonDown(InputComponent.Squeeze) : false;
    const grabPressed = kb.getKeyDown('KeyE') || rightGripDown;
    if (grabPressed && p.grabCooldown <= 0) {
      this.performGrab(p, this.opponentW);
      p.grabCooldown = 1.5;
      this.gameData.totalGrabs++;
    }

    // Dodge (Shift or Left Trigger)
    const leftTriggerDown = leftGP ? leftGP.getButtonDown(InputComponent.Trigger) : false;
    const dodgePressed = kb.getKeyDown('ShiftLeft') || kb.getKeyDown('ShiftRight') || leftTriggerDown;
    if (dodgePressed && p.dodgeCooldown <= 0) {
      this.performDodge(p, mx, mz);
      p.dodgeCooldown = 1.0;
      this.gameData.totalDodges++;
    }

    // Charge (hold Q)
    const chargeHeld = kb.getKeyPressed('KeyQ');
    if (chargeHeld && p.chargeCooldown <= 0) {
      p.isCharging = true;
      p.chargeTime += dt;
    } else if (p.isCharging) {
      if (p.chargeTime > 0.3) {
        this.performCharge(p, this.opponentW);
      }
      p.isCharging = false;
      p.chargeTime = 0;
      p.chargeCooldown = 2.0;
    }

    // Cooldowns
    p.pushCooldown = Math.max(0, p.pushCooldown - dt);
    p.grabCooldown = Math.max(0, p.grabCooldown - dt);
    p.dodgeCooldown = Math.max(0, p.dodgeCooldown - dt);
    p.chargeCooldown = Math.max(0, p.chargeCooldown - dt);
    p.pushAnim = Math.max(0, p.pushAnim - dt * 4);
    p.grabAnim = Math.max(0, p.grabAnim - dt * 3);
  }

  private playSFX(type: string) {
    if (this.gameData.sfxOn && this.audioSystemRef) {
      this.audioSystemRef.playSFX(type);
    }
  }

  private performPush(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const dist = attacker.pos.distanceTo(target.pos);

    if (dist < 1.2) {
      if (!target.isPlayerWrestler && target.dodgeTime <= 0) {
        const opp = this.gameData.currentOpponent;
        if (opp && Math.random() < opp.technique * 0.3) {
          const perpDir = new Vector3(-dir.z, 0, dir.x);
          target.vel.add(perpDir.multiplyScalar(DODGE_SPEED * 0.5));
          this.spawnParticles(target.pos, 0x44ff44, 4);
          return;
        }
      }

      const force = PUSH_FORCE / Math.max(0.5, target.weightVal);
      target.vel.add(dir.multiplyScalar(force));
      target.stagger = 0.2;
      attacker.pushAnim = 1;
      this.spawnParticles(
        new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
        0xffaa44, 8
      );
      this.shakeIntensity = 0.05;
      this.shakeDecay = 3;
      this.playSFX('push');
    }
  }

  private performGrab(attacker: Wrestler, target: Wrestler) {
    const dist = attacker.pos.distanceTo(target.pos);
    if (dist < 1.0) {
      const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
      const throwForce = (PUSH_FORCE * 1.5) / Math.max(0.5, target.weightVal);
      const throwAngle = (Math.random() > 0.5 ? 1 : -1) * Math.PI * 0.4;
      const cosA = Math.cos(throwAngle), sinA = Math.sin(throwAngle);
      const throwDir = new Vector3(dir.x * cosA - dir.z * sinA, 0, dir.x * sinA + dir.z * cosA);
      target.vel.add(throwDir.multiplyScalar(throwForce));
      target.stagger = 0.4;
      attacker.grabAnim = 1;
      this.spawnParticles(
        new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
        0xff44ff, 10
      );
      this.shakeIntensity = 0.08;
      this.shakeDecay = 3;
      this.playSFX('grab');
    }
  }

  private performDodge(wrestler: Wrestler, mx: number, mz: number) {
    let dx = mx, dz = mz;
    if (Math.abs(dx) < 0.1 && Math.abs(dz) < 0.1) {
      const away = new Vector3().subVectors(wrestler.pos, this.opponentW.pos).normalize();
      dx = away.x;
      dz = away.z;
    }
    const len = Math.sqrt(dx * dx + dz * dz);
    if (len > 0) {
      wrestler.dodgeDir.set(dx / len, 0, dz / len);
    } else {
      wrestler.dodgeDir.set(0, 0, -1);
    }
    wrestler.dodgeTime = DODGE_DURATION;
    this.spawnParticles(wrestler.pos.clone().setY(0.5), 0x44ccff, 6);
    this.playSFX('dodge');
  }

  private performCharge(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const chargeMultiplier = Math.min(attacker.chargeTime * 2, 3);
    const force = CHARGE_FORCE * chargeMultiplier / Math.max(0.5, target.weightVal);
    attacker.vel.add(dir.clone().multiplyScalar(5));
    const dist = attacker.pos.distanceTo(target.pos);
    if (dist < 2.0) {
      target.vel.add(dir.multiplyScalar(force));
      target.stagger = 0.5;
      this.spawnParticles(
        new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
        0xff8800, 15
      );
      this.shakeIntensity = 0.15;
      this.shakeDecay = 4;
      this.playSFX('charge');
    }
  }

  private updateAI(dt: number) {
    const opp = this.opponentW;
    const oppDef = this.gameData.currentOpponent;
    if (!oppDef || opp.stagger > 0 || opp.dodgeTime > 0) {
      opp.pushCooldown = Math.max(0, opp.pushCooldown - dt);
      opp.grabCooldown = Math.max(0, opp.grabCooldown - dt);
      opp.dodgeCooldown = Math.max(0, opp.dodgeCooldown - dt);
      opp.chargeCooldown = Math.max(0, opp.chargeCooldown - dt);
      return;
    }

    const toPlayer = new Vector3().subVectors(this.playerW.pos, opp.pos);
    const dist = toPlayer.length();
    toPlayer.normalize();
    opp.facing = Math.atan2(this.playerW.pos.x - opp.pos.x, this.playerW.pos.z - opp.pos.z);

    const oppDistFromCenter = Math.sqrt(opp.pos.x ** 2 + opp.pos.z ** 2);
    const playerDistFromCenter = Math.sqrt(this.playerW.pos.x ** 2 + this.playerW.pos.z ** 2);
    const moveSpeed = 2.5 * opp.speedVal;

    if (oppDistFromCenter > RING_RADIUS * 0.7) {
      const toCenter = new Vector3(-opp.pos.x, 0, -opp.pos.z).normalize();
      opp.vel.add(toCenter.multiplyScalar(moveSpeed * dt * 2));
    } else if (dist > 2.0) {
      if (Math.random() < oppDef.aggression) {
        opp.vel.add(toPlayer.clone().multiplyScalar(moveSpeed * dt));
      }
    } else if (dist > 1.0) {
      if (Math.random() < oppDef.technique * 0.5) {
        const perpDir = new Vector3(-toPlayer.z, 0, toPlayer.x);
        opp.vel.add(perpDir.multiplyScalar(moveSpeed * dt * 0.7));
      } else {
        opp.vel.add(toPlayer.clone().multiplyScalar(moveSpeed * dt * 0.8));
      }
    }

    // AI attacks
    if (dist < 1.2 && opp.pushCooldown <= 0) {
      if (Math.random() < oppDef.aggression * 0.8 * dt * 3) {
        this.performAIPush(opp, this.playerW);
        opp.pushCooldown = 0.6 / opp.speedVal;
      }
    }

    if (dist < 1.0 && opp.grabCooldown <= 0) {
      if (Math.random() < oppDef.technique * 0.5 * dt * 2) {
        this.performAIGrab(opp, this.playerW);
        opp.grabCooldown = 2.0 / opp.speedVal;
      }
    }

    if (playerDistFromCenter > RING_RADIUS * 0.6 && dist < 2.5 && opp.chargeCooldown <= 0) {
      if (Math.random() < oppDef.aggression * dt) {
        this.performCharge(opp, this.playerW);
        opp.chargeCooldown = 3.0;
      }
    }

    // Dodge player charge
    if (this.playerW.isCharging && dist < 2.0 && opp.dodgeCooldown <= 0) {
      if (Math.random() < oppDef.technique * 0.6) {
        const perpDir = new Vector3(-toPlayer.z, 0, toPlayer.x);
        opp.vel.add(perpDir.multiplyScalar(DODGE_SPEED * 0.4));
        opp.dodgeCooldown = 1.5;
        this.spawnParticles(opp.pos.clone().setY(0.5), 0x44ff44, 4);
      }
    }

    opp.pushCooldown = Math.max(0, opp.pushCooldown - dt);
    opp.grabCooldown = Math.max(0, opp.grabCooldown - dt);
    opp.dodgeCooldown = Math.max(0, opp.dodgeCooldown - dt);
    opp.chargeCooldown = Math.max(0, opp.chargeCooldown - dt);
    opp.pushAnim = Math.max(0, opp.pushAnim - dt * 4);
    opp.grabAnim = Math.max(0, opp.grabAnim - dt * 3);
  }

  private performAIPush(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const force = PUSH_FORCE * 0.8 / Math.max(0.5, target.weightVal);
    target.vel.add(dir.multiplyScalar(force));
    target.stagger = 0.15;
    attacker.pushAnim = 1;
    this.spawnParticles(
      new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
      0xffaa44, 6
    );
    this.shakeIntensity = 0.04;
    this.shakeDecay = 3;
    this.playSFX('push');
  }

  private performAIGrab(attacker: Wrestler, target: Wrestler) {
    const dir = new Vector3().subVectors(target.pos, attacker.pos).normalize();
    const throwForce = (PUSH_FORCE * 1.2) / Math.max(0.5, target.weightVal);
    const throwAngle = (Math.random() > 0.5 ? 1 : -1) * Math.PI * 0.3;
    const cosA = Math.cos(throwAngle), sinA = Math.sin(throwAngle);
    const throwDir = new Vector3(dir.x * cosA - dir.z * sinA, 0, dir.x * sinA + dir.z * cosA);
    target.vel.add(throwDir.multiplyScalar(throwForce));
    target.stagger = 0.3;
    attacker.grabAnim = 1;
    this.spawnParticles(
      new Vector3().lerpVectors(attacker.pos, target.pos, 0.5).setY(0.8),
      0xff44ff, 8
    );
    this.shakeIntensity = 0.06;
    this.shakeDecay = 3;
    this.playSFX('grab');
  }

  private updatePhysics(dt: number) {
    for (const w of [this.playerW, this.opponentW]) {
      if (w.dodgeTime > 0) {
