        w.group.rotation.z = Math.sin(time * 20) * 0.1 * w.stagger;
      } else {
        w.group.rotation.z = 0;
      }

      if (w.isCharging) {
        const intensity = Math.min(w.chargeTime * 2, 1);
        (w.belt.material as MeshStandardMaterial).emissiveIntensity = 0.4 + intensity * 1.5;
        w.group.scale.set(1 + intensity * 0.1, 1, 1 + intensity * 0.1);
      } else {
        (w.belt.material as MeshStandardMaterial).emissiveIntensity = 0.4;
        w.group.scale.set(1, 1, 1);
