    const edgeMat = this.ringEdgeGlow.material as MeshStandardMaterial;
    edgeMat.emissiveIntensity = 0.3 + Math.sin(time * 2) * 0.15;
    const scheme = COLOR_SCHEMES[this.gameData.colorScheme];
    edgeMat.color.set(scheme.accent);
    edgeMat.emissive.set(scheme.accent);

    for (const light of this.crowdLights) {
      light.intensity = 0.8 + Math.sin(time * 5 + light.position.x) * 0.2;
    }

    for (const dust of this.dustParticles) {
      dust.position.y = 0.4 + Math.sin(time * 1.5 + dust.position.x * 3) * 0.15;
      dust.position.x += Math.sin(time * 0.5 + dust.position.z) * dt * 0.1;
    }
  }

  private spawnParticles(pos: Vector3, color: number, count: number) {
    for (let i = 0; i < count; i++) {
      const geo = new SphereGeometry(0.04 + Math.random() * 0.04, 4, 3);
      const mat = new MeshStandardMaterial({
